CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_clientes_360`  AS SELECT `c`.`id` AS `id`, concat(`c`.`nombre`,' ',`c`.`apellido`) AS `cliente`, `c`.`cedula` AS `cedula`, `c`.`correo` AS `correo`, `c`.`fecha_registro` AS `fecha_registro`, `c`.`estado` AS `estado_cliente`, `c`.`segmento` AS `segmento`, (select count(0) from `servicios` `s` where `s`.`cliente_id` = `c`.`id` and `s`.`estado_comercial` <> 'retirado') AS `servicios_activos`, (select count(0) from `tickets` `t` where `t`.`cliente_id` = `c`.`id` and `t`.`estado` <> 'Cerrado') AS `tickets_abiertos`, (select count(0) from (`facturas` `f` join `servicios` `s2` on(`s2`.`id` = `f`.`servicio_id`)) where `s2`.`cliente_id` = `c`.`id` and `f`.`estado` = 'vencida') AS `facturas_vencidas`, (select max(`cc`.`ultimo_acceso`) from `clientes_credenciales` `cc` where `cc`.`cliente_id` = `c`.`id`) AS `ultima_actividad` FROM `clientes` AS `c` ;

-- --------------------------------------------------------

--
-- Structure for view `v_equipos_asignados`
--
DROP TABLE IF EXISTS `v_equipos_asignados`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_equipos_asignados`  AS SELECT `eq`.`id` AS `id`, `eq`.`tipo` AS `tipo`, `eq`.`marca` AS `marca`, `eq`.`modelo` AS `modelo`, `eq`.`direccion_mac` AS `direccion_mac`, `eq`.`puerto_nap` AS `puerto_nap`, `eq`.`estado_fisico` AS `estado_fisico`, `eq`.`estado_inventario` AS `estado_inventario`, `eq`.`propiedad` AS `propiedad`, `na`.`codigo` AS `nap_codigo`, `o`.`codigo` AS `olt_codigo`, `n`.`nombre` AS `nodo_nombre`, `s`.`id` AS `servicio_id`, `s`.`alias` AS `servicio_alias`, `ds`.`calle` AS `direccion_texto`, `c`.`id` AS `cliente_id`, concat(`c`.`nombre`,' ',`c`.`apellido`) AS `cliente` FROM ((((((`equipos` `eq` join `naps` `na` on(`na`.`id` = `eq`.`nap_id`)) left join `olts` `o` on(`o`.`id` = `na`.`olt_id`)) left join `nodos` `n` on(`n`.`id` = `o`.`nodo_id`)) left join `servicios` `s` on(`s`.`id` = `eq`.`servicio_id`)) left join `direccion_servicio` `ds` on(`ds`.`id` = `s`.`direccion_id`)) left join `clientes` `c` on(`c`.`id` = `s`.`cliente_id`)) WHERE `eq`.`estado_inventario` = 'asignado' AND `eq`.`servicio_id` is not null ;

