--
-- Structure for view `v_estado_cuenta_cliente`
--
DROP TABLE IF EXISTS `v_estado_cuenta_cliente`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_estado_cuenta_cliente`  AS SELECT `c`.`id` AS `id`, concat(`c`.`nombre`,' ',`c`.`apellido`) AS `cliente`, `c`.`cedula` AS `cedula`, `c`.`correo` AS `correo`, coalesce(sum(case when `f`.`estado` in ('pendiente','parcial','vencida') then greatest(`f`.`monto` - coalesce(`pv`.`total_pagado`,0),0) else 0 end),0) AS `saldo_pendiente`, count(distinct case when `f`.`estado` = 'vencida' then `f`.`id` end) AS `facturas_vencidas`, count(distinct case when `f`.`estado` = 'pagada' then `f`.`id` end) AS `facturas_pagadas`, max(`f`.`fecha_vencimiento`) AS `ultima_fecha_vencimiento` FROM (((`clientes` `c` left join `servicios` `s` on(`s`.`cliente_id` = `c`.`id`)) left join `facturas` `f` on(`f`.`servicio_id` = `s`.`id`)) left join (select `pagos`.`factura_id` AS `factura_id`,sum(`pagos`.`monto`) AS `total_pagado` from `pagos` where `pagos`.`estado` = 'validado' group by `pagos`.`factura_id`) `pv` on(`pv`.`factura_id` = `f`.`id`)) GROUP BY `c`.`id`, `c`.`nombre`, `c`.`apellido`, `c`.`cedula`, `c`.`correo` ;

-- --------------------------------------------------------

--
-- Structure for view `v_facturas_con_saldo`
--
DROP TABLE IF EXISTS `v_facturas_con_saldo`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `v_facturas_con_saldo`  AS SELECT `f`.`id` AS `id`, `f`.`servicio_id` AS `servicio_id`, `f`.`periodo` AS `periodo`, `f`.`monto` AS `monto`, `f`.`fecha_emision` AS `fecha_emision`, `f`.`fecha_vencimiento` AS `fecha_vencimiento`, `f`.`estado` AS `estado`, coalesce((select sum(`p`.`monto`) from `pagos` `p` where `p`.`factura_id` = `f`.`id` and `p`.`estado` = 'validado'),0) AS `total_pagado`, greatest(`f`.`monto` - coalesce((select sum(`p`.`monto`) from `pagos` `p` where `p`.`factura_id` = `f`.`id` and `p`.`estado` = 'validado'),0),0) AS `saldo`, `s`.`alias` AS `servicio_alias`, `c`.`id` AS `cliente_id`, concat(`c`.`nombre`,' ',`c`.`apellido`) AS `cliente`, `c`.`cedula` AS `cedula` FROM ((`facturas` `f` join `servicios` `s` on(`s`.`id` = `f`.`servicio_id`)) join `clientes` `c` on(`c`.`id` = `s`.`cliente_id`)) WHERE `f`.`estado` in ('pendiente','parcial','vencida') ;

